<span class="line">        <span class="token keyword">return</span> <span class="token builtin">list</span><span class="token punctuation">(</span>hashmap<span class="token punctuation">.</span>values<span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">)</span></span>
